head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.isRun = true;
scwin.g_SUBCOM_ACPT_NO = '';
scwin.g_ORGN_HDCOM_LNK_DISCLS_ACPT_NO = '';
scwin.g_HDCOM_ACPT_NO = '';
scwin.threadID;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {void}
 * @hidden N
 */
scwin.listSync = function() {
    let url = "/listingCommon.do?method=listGeneral&outputMessageId=LNKDISCLS_MONITORING_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.issueinfo.select.monitoring.linkdiscls" + "&{P}param01=" + rdo_MARKET_TP_CD.getValue() + // 시장구분
        "&{P}param02=" + rdo_MARKET_TP_CD.getValue() + // 시장구분
        "&{P}param03=" + edt_SDate.getValue();
    url += "&SCREN_ID=" + "ULDSTF33040.gfm";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_List.DataID = encodeURI(url);

    dts_List.reset();
};
scwin.g_hdcom_isur_cd;
scwin.g_hdcom_com_abbrv;
scwin.g_hdcom_lm_mkt_tp_cd;

/**
 * @method
 * @name setContnId
 * @description set Contn Id 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.g_SUBCOM_ACPT_NO = dts_List.getCellData(Number(obj), "SUBCOM_ACPT_NO");
    scwin.g_ORGN_HDCOM_LNK_DISCLS_ACPT_NO = dts_List.getCellData(Number(obj), "ORGN_HDCOM_LNK_DISCLS_ACPT_NO");
    scwin.g_HDCOM_ACPT_NO = dts_List.getCellData(Number(obj), "HDCOM_ACPT_NO");
    scwin.g_hdcom_isur_cd = dts_List.getCellData(Number(obj), "HDCOM_ISUR_CD");
    scwin.g_hdcom_com_abbrv = dts_List.getCellData(Number(obj), "HDCOM_COM_ABBRV");
    scwin.g_hdcom_lm_mkt_tp_cd = dts_List.getCellData(Number(obj), "HDCOM_LD_MKT_TP_NM");
};

/**
 * @method
 * @name openDisclViewerK
 * @description open Discl Viewer K 처리
 * @param {*} pAcptNo pAcptNo
 * @param {*} pViewerStat pViewerStat
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDisclViewerK = async function(pAcptNo, pViewerStat) {
    let vHttp;
    if (js_svrGubun === 'dev') {
        vHttp = g_dev_stf_url;
    } else {
        vHttp = g_real_stf_url;
    }
    let url = vHttp + "/dsclproc/ULDSTF10001.gfm?" + "gAcptNo=" + pAcptNo + "&gViewerStat=" + pViewerStat + "&frameID=" + frame.FrameID + "&gAccssAuthTpCd=01" + "&screnID=" + "ULDSTF33040.gfm";
    const winTitle = "공시뷰어";
    if ($c.frame.path("/top") !== undefined) {

        $c.frame.path("/top").WinOpen_child("viewer" + pAcptNo, url, winTitle, 1000, 800);
    } else {
        await $c.frame.CreateFrame("viewer" + pAcptNo, url, winTitle, 10, 10, 1000, 800, "window", 0, 0, true);
    }
};

/**
 * @method
 * @name setNoti
 * @description set Noti 처리
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.setNoti = function(rowcount) {
    let k_1 = 0;
    let k_2 = 0;
    let k_3 = 0;
    let k_4 = 0;
    for (let i = 1; i <= rowcount; i++) {
        const gLNK_DISCLS_MAKE_YN = dts_List.getCellData(i, "LNK_DISCLS_MAKE_YN");
        const gHDCOM_ACPT_NO = dts_List.getCellData(i, "HDCOM_ACPT_NO");
        const gSUBCOM_DISCLS_PROCS_STAT_CD = dts_List.getCellData(i, "SUBCOM_DISCLS_PROCS_STAT_CD");
        if (gLNK_DISCLS_MAKE_YN === 'Y') {
            k_1++;
            if (gSUBCOM_DISCLS_PROCS_STAT_CD === '30' || gSUBCOM_DISCLS_PROCS_STAT_CD === '35') {
                k_3++;
            }
            if (gSUBCOM_DISCLS_PROCS_STAT_CD === '40') {
                // 유보
                k_4++;
            }
        }
        if (gHDCOM_ACPT_NO !== '') {
            k_2++;
        }
    }
    const gStr = '연계공시생성대상건수 : ' + k_1 + '     연계공시생성건수 ' + k_2 + ' (승인건수 : ' + k_3 + ' , 유보건수 : ' + k_4 + ')';
    txb_NOTI.setValue(gStr);
};

/**
 * @method
 * @name listSyncAuto
 * @description list Sync Auto 처리
 * @returns {void}
 * @hidden N
 */
scwin.listSyncAuto = function() {

    scwin.threadID = setInterval('fn_list_sync()', 300000);
    scwin.isRun = true;
    scwin.setAlertTxt();
    scwin.listSync();
};

/**
 * @method
 * @name setAlertTxt
 * @description set Alert Txt 처리
 * @returns {void}
 * @hidden N
 */
scwin.setAlertTxt = function() {
    if (scwin.isRun) txtAlert.setValue("5분 마다 reload 되고 있습니다.");

    else txtAlert.setValue("reload 중지되었습니다.");
};

/**
 * @method
 * @name stopReload
 * @description stop Reload 처리
 * @returns {void}
 * @hidden N
 */
scwin.stopReload = function() {

    clearInterval(scwin.threadID);
    scwin.isRun = false;
    scwin.setAlertTxt();
};

/**
 * @method
 * @name btn_Reload_onclick
 * @description 「자동반복멈춤」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Reload_onclick = function() {
    scwin.stopReload();
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description 클릭된 값 변수에 셋팅
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.setContnId(row);
    if (colid === 'SUBCOM_COM_ABBRV') {
        await $c.frame.CreateFrame("ULDSTF33021" + row, "/issueinfo/ULDSTF33021.gfm", "연계공시 신청내역", 200, 70, 950, 560 + 30, "window", 0, 0, true);
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    scwin.stopReload();
    scwin.listSyncAuto();
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave("ULDSTF33040.gfm", SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_Grid, {fileName: "연계공시 모니터링", type: "8"});
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    await $c.win.alert(dts_List);
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    scwin.setNoti(rowcount);
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    await $c.win.closePopup();
};

/**
 * @method
 * @name btn_SDate_onclick
 * @description btn_SDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDate_onclick = function() {

    popUpCalendar2(edt_SDate);
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    scwin.init();
    scwin.listSyncAuto();
};
